                provider: "Passwordstate".to_string(),
                details: format!("Invalid reference format: '{}'", value),
                hint: "Expected 'id', 'id/field', 'title', or 'title/field'".to_string(),
                url: "https://fnox.jdx.dev/providers/overview".to_string(),
            }),
        }
