<script setup>
import { onMounted, ref } from "vue";

const sponsors = ref([]);
const error = ref(false);
const footerTiers = new Set(["title", "premier", "partner"]);
const sponsorFeedTimeoutMs = 5000;

const sponsorItems = (items) => (Array.isArray(items) ? items : []);
const sponsorFeedItems = (payload) => {
  const paid = sponsorItems(payload?.paid);
  return paid.length ? paid : sponsorItems(payload?.sponsors);
};
const isSafeUrl = (url) => {
  try {
    const { protocol } = new URL(url);
    return protocol === "https:" || protocol === "http:";
  } catch {
    return false;
  }
};
const isSafeImageUrl = (url) => {
  try {
    return new URL(url).protocol === "https:";
  } catch {
    return false;
  }
};
const isSponsor = (sponsor) =>
  sponsor &&
  typeof sponsor === "object" &&
  typeof sponsor.name === "string" &&
  typeof sponsor.url === "string" &&
  typeof sponsor.logo === "string" &&
  isSafeUrl(sponsor.url) &&
  isSafeImageUrl(sponsor.logo);

onMounted(async () => {
  const controller = new AbortController();
  const timeout = window.setTimeout(
    () => controller.abort(),
    sponsorFeedTimeoutMs,
  );

  try {
    const res = await fetch("https://jdx.dev/sponsors.json", {
      headers: { Accept: "application/json" },
      signal: controller.signal,
    });
    if (!res.ok) throw new Error(`Sponsor feed returned ${res.status}`);

    const payload = await res.json();
    sponsors.value = sponsorFeedItems(payload).filter(
      (sponsor) => isSponsor(sponsor) && footerTiers.has(sponsor.tier),
    );
  } catch {
    error.value = true;
    sponsors.value = [];
  } finally {
    window.clearTimeout(timeout);
  }
});
</script>

