<script setup>
import { ref } from "vue";

const storage = ref("vault");
const copyStatus = ref("");
async function copyInstall() {
  try {
    await navigator.clipboard.writeText("mise use -g fnox");
    copyStatus.value = "Copied";
  } catch {
    copyStatus.value = "Select the command to copy it";
  }
}
</script>

<template>
  <div class="fnox-home">
    <section class="home-hero" aria-labelledby="home-title">
      <div class="hero-copy">
        <p class="eyebrow"><span aria-hidden="true" class="status-dot"></span> Fort Knox for your secrets</p>
        <h1 id="home-title">Your secrets.<br /><span>Where you need them.</span></h1>
        <p class="hero-lead">From your vault to your terminal. Load secrets from encrypted files, password managers, and cloud services with one command.</p>
        <div class="hero-actions">
          <a class="home-button primary" href="/guide/quick-start">Get started <span aria-hidden="true">↗</span></a>
          <a class="home-button secondary" href="/providers/overview">Find your provider <span aria-hidden="true">→</span></a>
        </div>
        <div class="install-command">
          <span class="prompt" aria-hidden="true">$</span>
          <code>mise use -g fnox</code>
          <button type="button" aria-label="Copy installation command" @click="copyInstall">Copy</button>
        </div>
        <p class="install-note" aria-live="polite">{{ copyStatus || "Open source · MIT licensed · Built in Rust" }}</p>
      </div>
      <div class="hero-demo" aria-label="Example fnox configuration and command">
        <div class="demo-topbar">
          <div class="demo-file"><img src="/logo.svg" alt="" width="24" height="24" /> fnox.toml</div>
          <span class="demo-label">COMMIT THE CONFIG</span>
        </div>
        <div class="storage-switch" aria-label="Example storage model">
          <button type="button" :aria-pressed="storage === 'vault'" @click="storage = 'vault'">Vault references</button>
          <button type="button" :aria-pressed="storage === 'encrypted'" @click="storage = 'encrypted'">Encrypted in git</button>
        </div>
        <pre v-if="storage === 'vault'"><code><span class="code-comment"># Connect the vault you already use</span>
<span class="code-section">[providers.op]</span>
type = <span class="code-string">"1password"</span>
vault = <span class="code-string">"Engineering"</span>

<span class="code-section">[secrets.DATABASE_URL]</span>
provider = <span class="code-string">"op"</span>
value = <span class="code-string">"Database/url"</span></code></pre>
        <pre v-else><code><span class="code-comment"># fnox set writes the ciphertext for you</span>
<span class="code-section">[providers.age]</span>
type = <span class="code-string">"age"</span>
recipients = <span class="code-string">["age1…"]</span>

<span class="code-section">[secrets.DATABASE_URL]</span>
provider = <span class="code-string">"age"</span>
value = <span class="code-string">"YWdlLWVuY3J5cHRpb24…"</span></code></pre>
        <div class="demo-run">
          <span class="demo-label">RUN WITH SECRETS</span>
          <pre><code><span class="prompt">$</span> fnox exec -- npm start</code></pre>
          <p><span aria-hidden="true">↳</span> DATABASE_URL is available to your app.</p>
        </div>
        <p class="demo-caption">{{ storage === 'vault' ? 'The reference goes in git. The value stays in your vault.' : 'Ciphertext and recipient are abbreviated. Keep your private key outside git.' }}</p>
