text(await tools.exec_command({cmd:"cat > /tmp/fnox-cli-examples.py <<'PY'
from pathlib import Path
import json
entries={
'activate':('Enable the hook for your shell. Fish, Nushell, and PowerShell use different activation syntax; follow the shell guide for those commands.', 'eval "$(fnox activate bash)"\n# Zsh:\neval "$(fnox activate zsh)"', ['/guide/shell-integration']),
'deactivate':('After shell activation, the fnox shell function applies this command to the current session. Remove the activation line from your startup file to disable it in future shells.', 'fnox deactivate', ['/guide/shell-integration']),
'check':('By default, check validates required secrets. Use --all to also check secrets whose missing-value policy is warn or ignore. The command validates resolution without printing resolved values.', 'fnox check --all\nfnox check --all --profile production', ['/guide/troubleshooting','/guide/missing-secrets']),
'completion':('Generate completions for the named shell. Install or source the output according to that shell’s completion setup; generating it alone does not change your shell.', 'fnox completion bash > fnox.bash\nfnox completion zsh > _fnox', ['/guide/shell-integration']),
'config-files':('Inspect the effective file stack before debugging an unexpected value. An explicit config path skips directory discovery and adjacent local overrides; the global config still loads.', 'fnox config-files\nfnox --profile staging config-files\nfnox -c ./fnox.toml config-files', ['/guide/hierarchical-config']),
'doctor':('Check the local fnox setup, then test a specific provider or resolve all configured secrets to narrow down a failure.', 'fnox doctor\nfnox provider test op\nfnox check --all', ['/guide/troubleshooting']),
'edit':('Open configuration in your editor. Configure EDITOR (or VISUAL) first. Use fnox set for an individual value so the selected provider handles storage.', 'EDITOR=vim fnox edit', ['/reference/environment#editor','/cli/set']),
'exec':('Put fnox options before --. Arguments after -- belong to the child command. To expand an injected variable in a shell expression, defer expansion to a child shell with single quotes.', 'fnox exec -- npm start\nfnox exec --profile production --if-missing error -- ./deploy.sh\nfnox exec -- sh -c \'test -n "$DATABASE_URL"\'', ['/guide/how-it-works','/guide/profiles']),
'export':('Exports contain real resolved values, not dummy placeholders. By default, export follows shell injection settings; --all also includes exec-only and non-injected secrets. Protect output files and keep them out of git.', 'fnox export --format json\n# Create a private plaintext file (POSIX shell)\numask 077\nfnox export --output .env', ['/guide/import-export','/reference/configuration#env-1']),
'get':('Print one resolved value to stdout. Use check --all when you only need to verify access without displaying the secret.', 'fnox get DATABASE_URL\nfnox get DATABASE_URL --profile staging', ['/guide/how-it-works','/cli/check']),
'import':('Configure an encryption provider first. Remote storage providers are not import targets. When stdin carries the import data, use --force because stdin cannot also answer the confirmation prompt.', 'fnox import --input .env --provider age --dry-run\nfnox import --input .env --provider age\ncat secrets.json | fnox import json --provider age --force', ['/guide/import-export']),
'init':('In a terminal, the wizard can configure a provider and select it as the default. --skip-wizard creates a minimal config; it does not enable encryption. Configure a provider before storing sensitive values.', 'fnox init\nfnox init --skip-wizard', ['/guide/quick-start']),
'list':('Lists the secrets configured in fnox. It does not enumerate every remote vault item. Values are hidden unless you request --values.', 'fnox list\nfnox list --sources\nfnox list --profile production', ['/guide/hierarchical-config','/cli/tui']),
'mcp':('Run a stdio MCP server from the project directory. Configure its secret allowlist and authenticate to providers before starting the client.', 'fnox mcp\nfnox --profile staging mcp', ['/guide/mcp']),
'profiles':('Inspect the available profile names before selecting or composing them. Use --write-profile when writing with multiple active profiles.', 'fnox profiles\nfnox -P aws,staging list', ['/guide/profiles']),
'provider':('Manage configured provider instances. The instance name, such as op, is distinct from the provider type, such as 1password.', 'fnox provider list\nfnox provider test op', ['/providers/overview']),
'provider/add':('Creates a provider configuration. Some types require interactive setup; others create placeholders that you must replace before use. For this command, the aws and gcp choices correspond to the aws-sm and gcp-sm config types.', 'fnox provider add op 1password\nfnox provider add sync-age age --global', ['/providers/overview','/guide/golden-path']),
'provider/list':('List configured provider instances for the selected profile. To find the supported provider types, use the provider catalog.', 'fnox provider list\nfnox --profile production provider list', ['/providers/overview']),
'provider/remove':('Remove a provider definition from the configuration. Update secrets that reference it before removing it; this command does not delete the remote vault or its items.', 'fnox provider remove old-vault', ['/providers/overview']),
'provider/test':('Use a configured instance name, not its type. A successful connection test does not guarantee that every referenced item exists; check --all validates those references too.', 'fnox provider test op\nfnox provider test --all\nfnox check --all', ['/guide/troubleshooting']),
'reencrypt':('After changing recipients, re-encrypt with an identity that can still decrypt the existing ciphertext. Repeat for each affected profile. This changes the encryption, not the underlying secret value.', 'fnox reencrypt --provider age --dry-run\nfnox reencrypt --provider age\nfnox reencrypt --provider age --profile staging', ['/providers/age#adding-a-new-team-member']),
'remove':('Remove a secret definition from fnox configuration. The command does not delete or revoke the original value in a remote provider.', 'fnox remove OLD_TOKEN --dry-run\nfnox remove OLD_TOKEN', ['/cli/set','/guide/profiles']),
'scan':('Scan files for potential secrets using heuristics. Findings need review; a clean scan does not prove that files or git history contain no secrets.', 'fnox scan .\nfnox scan . --format json\nfnox scan . --ignore "vendor/**"', ['/providers/plain']),
'set':('Configure a provider first. Omitting VALUE prompts with hidden input in a terminal or reads piped stdin. Without a selected provider, set writes a plaintext default. --from-file preserves file contents, including trailing newlines.', 'fnox set DATABASE_URL --provider age\nfnox set SSH_PRIVATE_KEY --provider age --from-file ~/.ssh/id_ed25519\nfnox set DATABASE_URL --profile staging --provider age', ['/guide/quick-start','/reference/configuration#as-file']),
'sponsors':('Show project sponsors in the terminal.', 'fnox sponsors', ['/contributing']),
'sync':('Use a configured encryption provider as the target. --local-file writes a personal cache next to the project config; add that file to .gitignore. Run sync again after source values change.', 'fnox sync --provider sync-age --local-file --dry-run\nfnox sync --provider sync-age --local-file\nfnox sync --provider sync-age --local-file DATABASE_URL', ['/guide/sync']),
