use crate::commands::Cli;
use crate::config::Config;
use crate::error::{FnoxError, Result};
use crate::shell;
use crate::temp_file_secrets::create_persistent_secret_file;
use console;
use indexmap::IndexMap;
use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use strum::{Display, EnumString, VariantNames};

/// Supported export formats
#[derive(Debug, Clone, Copy, usage_rs::ValueEnum, Display, EnumString, VariantNames)]
#[strum(serialize_all = "lowercase")]
pub enum ExportFormat {
    /// Environment variable format (KEY=value)
    Env,
    /// POSIX shell format (export KEY=value)
    Shell,
    /// JSON format
    Json,
    /// YAML format
    Yaml,
    /// TOML format
    Toml,
}

/// Export secrets in various formats
#[derive(usage_rs::Args)]
#[usage(alias("ex"))]
pub struct ExportCommand {
    /// Export format
    #[usage(short, long, default = "env", value_enum)]
    format: ExportFormat,

    /// Show what would be exported without writing to a file
    #[usage(short = 'n', long)]
    dry_run: bool,

    /// Output file (default: stdout)
    #[usage(short = 'o', long)]
    output: Option<PathBuf>,

    /// Include secrets with env = false or env = "exec" (excluded by default)
    #[usage(long)]
    all: bool,

    /// Include metadata comments in env and shell output
    #[usage(long)]
    header: bool,
}

#[derive(Serialize, Deserialize)]
struct ExportData {
    secrets: IndexMap<String, String>,
    metadata: Option<ExportMetadata>,
}

#[derive(Serialize, Deserialize)]
struct ExportMetadata {
    profile: String,
    exported_at: String,
    total_secrets: usize,
}

impl ExportCommand {
    pub async fn run(&self, cli: &Cli, config: Config) -> Result<()> {
        let profile = Config::get_profiles(cli.profile.as_slice());
        tracing::debug!(
            "Exporting secrets from profiles '{}'",
            Config::display_profiles(&profile)
        );

        let mut profile_secrets = config.get_secrets(&profile)?;

        // Export is a shell-injection surface (the mise plugin evaluates it),
        // so exclude secrets not meant for the shell unless --all is passed.
        // Filtering before resolution avoids auth prompts for hidden secrets.
        if !self.all {
            profile_secrets.retain(|_, sc| sc.env_mode().in_shell());
        }

        // Resolve secrets using batch resolution for better performance
        let resolved_secrets = crate::daemon::resolve_batch(
            cli,
            &config,
            &profile,
            &profile_secrets,
            crate::daemon::Purpose::Export,
            true,
        )
        .await?;

        // Build secrets map, preserving insertion order
        // For file-based secrets, create persistent temp files
        let mut secrets = IndexMap::new();
        for (key, value_opt) in resolved_secrets {
            if let Some(value) = value_opt {
                // Check if this secret should be file-based
                if let Some(secret_config) = profile_secrets.get(&key) {
            };

            if !key.is_empty() {
                secrets.insert(key.to_string(), value);
            }
        }
        Ok(())
    }

    fn parse_json(&self, input: &str, source_name: &str) -> Result<HashMap<String, String>> {
        let data: serde_json::Value = serde_json::from_str(input).map_err(|e| {
            // serde_json provides line and column
            let offset = self.offset_from_line_col(input, e.line(), e.column());
            FnoxError::ImportParseErrorWithSource {
                format: "JSON".to_string(),
                details: e.to_string(),
                src: Arc::new(NamedSource::new(source_name, Arc::new(input.to_string()))),
                span: SourceSpan::new(offset.into(), 1usize),
            }
        })?;
        self.extract_string_values(&data)
    }

    fn parse_yaml(&self, input: &str, source_name: &str) -> Result<HashMap<String, String>> {
        let data: serde_yaml::Value = serde_yaml::from_str(input).map_err(|e| {
            // serde_yaml provides location via e.location()
            // Note: serde_yaml uses 0-indexed line/column, so we add 1 for our 1-indexed function
            if let Some(loc) = e.location() {
                let offset = self.offset_from_line_col(input, loc.line() + 1, loc.column() + 1);
                FnoxError::ImportParseErrorWithSource {
                    format: "YAML".to_string(),
                    details: e.to_string(),
                    src: Arc::new(NamedSource::new(source_name, Arc::new(input.to_string()))),
                    span: SourceSpan::new(offset.into(), 1usize),
                }
            } else {
                FnoxError::Config(format!("Failed to parse YAML: {}", e))
            }
        })?;
        self.extract_string_values(&data)
    }

    fn parse_toml(&self, input: &str, source_name: &str) -> Result<HashMap<String, String>> {
        let data: serde_json::Value = toml_edit::de::from_str(input).map_err(|e| {
            // toml_edit provides span via e.span()
            if let Some(span) = e.span() {
                FnoxError::ImportParseErrorWithSource {
                    format: "TOML".to_string(),
                    details: e.to_string(),
                    src: Arc::new(NamedSource::new(source_name, Arc::new(input.to_string()))),
                    span: SourceSpan::new(span.start.into(), span.end - span.start),
                }
            } else {
                FnoxError::Config(format!("Failed to parse TOML: {}", e))
            }
        })?;
        self.extract_string_values(&data)
    }

    /// Convert line/column (1-indexed) to byte offset for miette source spans.
    ///
    /// Handles both LF and CRLF line endings (CRLF is handled because we detect
    /// line boundaries at '\n', and '\r' is just part of line content).
    /// The column is treated as a character count, which is converted to the
    /// correct byte offset for multi-byte UTF-8.
    ///
```

## Export secrets

### Export formats

```bash
# Export as .env format (default)
fnox export

# Export as sourceable POSIX shell
fnox export --format shell

# Export as JSON
fnox export --format json

# Export as YAML
fnox export --format yaml

# Export as TOML
fnox export --format toml

# Include metadata comments in env/shell output
fnox export --header
```

### Save to file

Create private output files and keep them out of version control. In a POSIX shell, `umask 077` restricts permissions on newly created files:

```sh
umask 077
```

```bash
# Export to file
fnox export > .env
fnox export --format shell > secrets.sh
fnox export --format json > secrets.json
fnox export --format yaml > secrets.yaml
fnox export --format toml > secrets.toml
```

### Export with profile

```bash
# Export production secrets
fnox export --profile production > .env.production

# Export staging secrets as JSON
fnox export --profile staging --format json > staging.json
```

## Migration workflows

### From .env to fnox

First [configure an age provider](/guide/quick-start), then preview and import:

```sh
fnox import -i .env --provider age --dry-run
fnox import -i .env --provider age
fnox check --all
fnox exec -- npm start
```

Review the encrypted configuration before committing. Keep `.env` ignored, and remove the plaintext file when the application no longer needs it.

### From a remote provider to local encryption

To retain remote references and make a personal cache, use [`fnox sync`](/guide/sync).

To migrate values into an encryption provider permanently, export and import through a pipe in Bash or Zsh:

```sh
fnox export --profile production --format json |
  fnox import json --provider age --force
```

